<template><view class="page"><view class="bar"><text @tap="back">‹</text><text>{{ name || '相册' }}</text><text>{{ photos.length }} 张</text></view><scroll-view class="scroll" scroll-y><view class="content"><ImageUploadGrid v-model="images" :max-count="30" :upload-task-factory="createPhotoTask" @remove="removePhoto"/><text class="hint">上传完成后立即进入此空间相册；首张照片会自动成为封面。</text></view></scroll-view></view></template>
<script>import{createAlbumPhotoUploadTask,deleteAlbumPhoto,getAlbumPhotos,normalizeAssetUrl}from'../../services/api';import ImageUploadGrid from'../../components/ImageUploadGrid.vue';export default{components:{ImageUploadGrid},data(){return{spaceId:'',albumId:'',name:'',photos:[],images:[]}},onLoad(q){this.spaceId=q.spaceId||'';this.albumId=q.albumId||'';this.name=decodeURIComponent(q.name||'');this.load()},methods:{normalizeAssetUrl,async load(){try{this.photos=await getAlbumPhotos(this.spaceId,this.albumId);this.images=this.photos.map(p=>({id:'remote-'+p.id,url:normalizeAssetUrl(p.thumb_url||p.url),localPath:normalizeAssetUrl(p.thumb_url||p.url),status:'success',progress:100,remote:p}))}catch(e){uni.showToast({title:'相册读取失败',icon:'none'})}},createPhotoTask(path,fileName,mime,onProgress){return createAlbumPhotoUploadTask(this.spaceId,this.albumId,path,fileName,mime,onProgress)},async removePhoto(item){const photo=item.remote;if(!photo||!photo.id)return;try{await deleteAlbumPhoto(this.spaceId,this.albumId,photo.id);this.photos=this.photos.filter(p=>p.id!==photo.id)}catch(e){uni.showToast({title:'删除照片失败，已重新加载',icon:'none'});this.load()}},back(){uni.navigateBack({delta:1})}}}</script>
<style scoped>.page{height:100vh;background:#f1eee5}.bar{height:calc(var(--status-bar-height) + 104rpx);padding:var(--status-bar-height) 28rpx 0;box-sizing:border-box;display:flex;align-items:center;justify-content:space-between;background:#fffdf8;color:#17211d;font-family:Georgia,'Songti SC',serif;font-size:27rpx;font-weight:700}.bar text:first-child{width:56rpx;color:#163a2b;font-size:56rpx;line-height:52rpx}.bar text:last-child{width:80rpx;color:rgba(23,33,29,.45);font-family:inherit;font-size:19rpx;text-align:right}.scroll{height:calc(100vh - var(--status-bar-height) - 104rpx)}.content{padding:28rpx}.hint{display:block;margin:20rpx 4rpx;color:rgba(23,33,29,.46);font-size:19rpx;line-height:30rpx}</style>
